/// Salvage: turn the uncommitted files of a worktree into a commit on a branch, so a worktree is never the only place work lives.
///
/// It is git plumbing with a temporary index, so the worktree itself is not touched: its files, its index, its HEAD and its
/// branch are exactly as they were, and an agent working in it notices nothing. The commit holds the worktree's HEAD as its
/// parent (and the previous salvage commit as a second one, so earlier salvages stay reachable) and the files git reports as
/// changed that are somebody's work (build output is regenerated by definition and is left out, as the forced removal of a
/// merged worktree already treats it).
///
/// Idempotent by tree id: a second salvage of the same files makes no commit.
module SageFs.HygieneSalvage

open System
open System.IO
open System.Threading.Tasks
open SageFs.WorkspaceHygiene
open SageFs.HygieneGather

[<RequireQualifiedAccess>]
type SalvageResult =
  /// Nothing in the worktree is somebody's uncommitted work.
  | NothingToSalvage
  /// The branch already holds exactly these files.
  | AlreadySalvaged of branch: string * sha: string
  | Salvaged of branch: string * sha: string * files: int
  | CouldNotSalvage of why: string

/// The identity the salvage commit is made under, so it never depends on the machine's git config.
let private identity : (string * string) list =
  [ "GIT_AUTHOR_NAME", "SageFs hygiene"
    "GIT_AUTHOR_EMAIL", "hygiene@sagefs.local"
    "GIT_COMMITTER_NAME", "SageFs hygiene"
    "GIT_COMMITTER_EMAIL", "hygiene@sagefs.local" ]

/// The ref a worktree's uncommitted files go to: under refs/sagefs/salvage, not a branch, so `git push --all` does not publish
/// what may be a local `.env` (`SalvageRefs`).
let branchFor (worktreePath: string) : string =
  SalvageRefs.refPrefix + Path.GetFileName(worktreePath.TrimEnd('/', '\\'))

let private text (result: GitResult) : Result<string, string> =
  match result with
  | GitResult.Output out -> Result.Ok(out.Trim())
  | GitResult.Exit(code, stderr) -> Result.Error(sprintf "git exited %d: %s" code stderr)
  | GitResult.Unavailable detail -> Result.Error detail

let private mapT (f: 'a -> 'b) (t: Task<'a>) : Task<'b> =
  task {
    let! value = t
    return f value
  }

/// Commit the worktree's real uncommitted files to `refs/sagefs/salvage/<name>`. Never throws: a git that will not answer is a result.
let salvage (git: GitWithEnv) (worktreePath: string) : Task<SalvageResult> =
  task {
    let plain args = git worktreePath [] args
    match! changedFiles (fun dir args -> git dir [] args) worktreePath with
    | Result.Error why -> return SalvageResult.CouldNotSalvage(UnknownReason.describe why)
    | Result.Ok files ->
      let real = files |> List.filter (fun f -> f.Origin = ChangeOrigin.Real) |> List.map (fun f -> f.Path)
      match real with
      | [] -> return SalvageResult.NothingToSalvage
      | _ ->
        let branch = branchFor worktreePath
        let index = Path.Combine(Path.GetTempPath(), sprintf "sagefs-hygiene-index-%s" (Guid.NewGuid().ToString "N"))
        let env = [ "GIT_INDEX_FILE", index; "GIT_LITERAL_PATHSPECS", "1" ] @ identity
        try
          match! plain [ "rev-parse"; "HEAD" ] |> mapT text with
          | Result.Error why -> return SalvageResult.CouldNotSalvage why
          | Result.Ok head ->
            let step args = git worktreePath env args |> mapT text
            match! step [ "read-tree"; head ] with
            | Result.Error why -> return SalvageResult.CouldNotSalvage why
            | Result.Ok _ ->
              // -f: an ignored file (a local .env) is work too, and a plain add would skip it.
              match! step ([ "add"; "-A"; "-f"; "--" ] @ real) with
              | Result.Error why -> return SalvageResult.CouldNotSalvage why
              | Result.Ok _ ->
                match! step [ "write-tree" ] with
                | Result.Error why -> return SalvageResult.CouldNotSalvage why
                | Result.Ok tree ->
                  let! previous = plain [ "rev-parse"; "--verify"; "--quiet"; branch ] |> mapT text
                  let previousTip = match previous with | Result.Ok sha when sha <> "" -> Some sha | _ -> None
                  let! previousTree =
                    match previousTip with
                    | Some sha -> plain [ "rev-parse"; sha + "^{tree}" ] |> mapT (fun r -> match text r with | Result.Ok t -> Some t | Result.Error _ -> None)
                    | None -> Task.FromResult None
                  match previousTip, previousTree with
                  | Some sha, Some t when t = tree -> return SalvageResult.AlreadySalvaged(branch, sha)
                  | _ ->
                    let parents =
                      [ "-p"; head ] @ (match previousTip with | Some sha -> [ "-p"; sha ] | None -> [])
                    let message = sprintf "salvage: %d uncommitted file(s) from %s" (List.length real) (Path.GetFileName(worktreePath.TrimEnd('/', '\\')))
                    match! step ([ "commit-tree"; tree ] @ parents @ [ "-m"; message ]) with
                    | Result.Error why -> return SalvageResult.CouldNotSalvage why
                    | Result.Ok sha ->
                      let move =
                        match previousTip with
                        | Some old -> [ "update-ref"; branch; sha; old ]
                        | None -> [ "update-ref"; branch; sha; "" ]
                      match! step move with
                      | Result.Error why -> return SalvageResult.CouldNotSalvage why
                      | Result.Ok _ -> return SalvageResult.Salvaged(branch, sha, List.length real)
        finally
          try File.Delete index
          with
          | :? IOException
          | :? UnauthorizedAccessException -> ()
  }

/// Every salvage ref in a repository, newest information first. A git that will not answer is `NotListed`, never an empty list.
let listRefs (git: Git) (repo: string) : Task<SalvageRefs.Listing> =
  task {
    match! git repo [ "for-each-ref"; "--format=%(refname)%09%(objectname)%09%(committerdate:unix)"; SalvageRefs.refPrefix ] with
    | GitResult.Output out ->
      let parsed =
        out.Split([| '\n' |], StringSplitOptions.RemoveEmptyEntries)
        |> Array.toList
        |> List.choose (fun line ->
          match line.Split('\t') with
          | [| refName; sha; unix |] when refName.StartsWith(SalvageRefs.refPrefix, StringComparison.Ordinal) ->
            let seconds = match Int64.TryParse unix with | true, s -> s | false, _ -> 0L
            Some
              ({ Name = refName.Substring SalvageRefs.refPrefix.Length
                 Ref = refName
                 Sha = sha
                 At = DateTimeOffset.FromUnixTimeSeconds(seconds).UtcDateTime } : SalvageRefs.SalvageRef)
          | _ -> None)
      return SalvageRefs.Listing.Listed parsed
    | GitResult.Exit(code, stderr) -> return SalvageRefs.Listing.NotListed(sprintf "git exited %d: %s" code stderr)
    | GitResult.Unavailable detail -> return SalvageRefs.Listing.NotListed detail
  }
